// Generate an AES-256 key from Qrypt quantum entropy.
// Run with: qrypt-run qrypt-aes256/generate-key.mjs   (Node 20.12+, no dependencies)
//
// The token and the key are never printed. The key is written to keys/aes256.key
// (mode 0600); only a short SHA-256 fingerprint is shown so you can identify it.

import { createCipheriv, createDecipheriv, createHash, randomBytes } from "node:crypto";
import { writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const projectDir = dirname(fileURLToPath(import.meta.url));
const envPath = join(projectDir, "..", ".env");
const keyPath = join(projectDir, "keys", "aes256.key");

process.loadEnvFile(envPath);
const token = process.env.QRYPT_API_KEY;
if (!token) {
  console.error("QRYPT_API_KEY is not set in .env");
  process.exit(1);
}

const baseUrl = process.env.QRYPT_BASE_URL ?? "https://api-eus.qrypt.com";
const url = `${baseUrl}/api/v1/quantum-entropy?size=1`; // size is in KiB

const res = await fetch(url, {
  headers: {
    Authorization: `Bearer ${token}`,
    Accept: "application/json",
    "User-Agent": "qrypt-aes256-keygen/1.0",
  },
});

if (!res.ok) {
  const hints = {
    400: "size out of range (must be 1-512 KiB)",
    401: "auth header missing, malformed, or token expired",
    403: "token invalid or monthly quota exhausted",
    429: "rate limited; wait 10+ seconds before trying again",
  };
  console.error(`Qrypt API error ${res.status}: ${hints[res.status] ?? "service busy or erroring; try later"}`);
  process.exit(1);
}

const body = await res.json();
const entropy = Buffer.from(body.random[0], "base64");
if (entropy.length < 32) {
  console.error(`Expected at least 32 bytes of entropy, got ${entropy.length}`);
  process.exit(1);
}
const key = entropy.subarray(0, 32);

// Sanity check: AES-256-GCM encrypt/decrypt round trip.
const iv = randomBytes(12);
const plaintext = Buffer.from("hello, quantum world");
const cipher = createCipheriv("aes-256-gcm", key, iv);
const ciphertext = Buffer.concat([cipher.update(plaintext), cipher.final()]);
const tag = cipher.getAuthTag();
const decipher = createDecipheriv("aes-256-gcm", key, iv);
decipher.setAuthTag(tag);
const roundTrip = Buffer.concat([decipher.update(ciphertext), decipher.final()]);
if (!roundTrip.equals(plaintext)) {
  console.error("AES-256-GCM round trip failed");
  process.exit(1);
}

writeFileSync(keyPath, key, { mode: 0o600 });

const fingerprint = createHash("sha256").update(key).digest("hex").slice(0, 16);
console.log(`Received ${entropy.length} bytes of quantum entropy`);
console.log(`AES-256 key (32 bytes) saved to ${keyPath}`);
console.log(`Key fingerprint (SHA-256, first 16 hex): ${fingerprint}`);
console.log("AES-256-GCM encrypt/decrypt round trip: OK");

